"""Regenerate tests/fixtures/acl/cases.json. Windows only; run by hand.

Each case is an SDDL string turned into a self-relative binary security
descriptor by Windows itself (ConvertStringSecurityDescriptorToSecurityDescriptorW),
then hex-encoded. The Python hook and the PowerShell writer both evaluate
these bytes and must reach the same verdict and first problem code.

A few "nested size" cases are made by editing the generated bytes, because
Windows will not produce a malformed descriptor on purpose.

Usage:  python tests/fixtures/acl/make_fixtures.py
"""
from __future__ import annotations

import ctypes
import json
import struct
import sys
from ctypes import wintypes
from pathlib import Path
from typing import Any, Dict, List, Optional

HERE = Path(__file__).resolve().parent

# Owner Administrators, protected DACL: the setup SDDL from design section 5.
SETUP = "O:BAD:PAI(A;OICI;FA;;;BA)(A;OICI;FA;;;SY)(A;OICI;0x1200a9;;;BU)"
FILE_SDDL = "O:BAD:PAI(A;;FA;;;BA)(A;;FA;;;SY)(A;;0x1200a9;;;BU)"
# C:\ProgramData's owner and DACL as read from a Windows 11 install (entry
# order and masks as Windows stores them). Users may create files and folders
# (0x116) but not delete or re-permission anything, which passes rule I5.
PROGRAM_DATA = ("O:SYD:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)(A;OICIIO;GA;;;CO)"
                "(A;OICI;0x1200a9;;;BU)(A;CI;0x116;;;BU)")


def sddl_to_bytes(sddl: str) -> bytes:
    advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    convert = advapi32.ConvertStringSecurityDescriptorToSecurityDescriptorW
    convert.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, ctypes.POINTER(ctypes.c_void_p),
                        ctypes.POINTER(wintypes.ULONG)]
    convert.restype = wintypes.BOOL
    kernel32.LocalFree.argtypes = [ctypes.c_void_p]
    kernel32.LocalFree.restype = ctypes.c_void_p
    pointer = ctypes.c_void_p()
    size = wintypes.ULONG()
    if not convert(sddl, 1, ctypes.byref(pointer), ctypes.byref(size)):
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        return ctypes.string_at(pointer, size.value)
    finally:
        kernel32.LocalFree(pointer)


def dacl_offset(data: bytes) -> int:
    return struct.unpack_from("<I", data, 16)[0]


def first_ace_offset(data: bytes) -> int:
    return dacl_offset(data) + 8


def patch(data: bytes, offset: int, fmt: str, value: int) -> bytes:
    buffer = bytearray(data)
    struct.pack_into(fmt, buffer, offset, value)
    return bytes(buffer)


cases: List[Dict[str, Any]] = []


def add(case_id: str, role: str, ok: bool, problem: Optional[str], *, sddl: str = "",
        data: Optional[bytes] = None, reparse: bool = False) -> None:
    raw = data if data is not None else sddl_to_bytes(sddl)
    cases.append({"id": case_id, "role": role, "ok": ok, "problem": problem,
                  "reparse": reparse, "sddl": sddl, "hex": raw.hex()})


def main() -> None:
    if sys.platform != "win32":
        raise SystemExit("Windows only: the bytes come from the Windows SDDL converter.")

    for role in ("folder", "file", "ancestor"):
        add(f"setup-{role}", role, True, None, sddl=SETUP)
    add("file-sddl", "file", True, None, sddl=FILE_SDDL)
    add("users-write", "file", False, "write-right",
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;0x1200a9;;;BU)(A;;0x2;;;BU)")
    add("users-write-dac-only", "file", False, "write-right",
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;0x40000;;;BU)")
    add("users-append-only", "file", False, "write-right",
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;0x4;;;BU)")
    add("everyone-generic-write", "file", False, "write-right",
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;GW;;;WD)")
    add("users-delete", "file", False, "write-right",
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;SD;;;BU)")
    add("inherit-only-write", "folder", True, None,
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;OICIIO;FA;;;BU)")
    add("deny-entry", "file", True, None,
        sddl="O:BAD:PAI(D;;FA;;;BU)(A;;FA;;;BA)")
    add("trusted-installer-full", "file", True, None,
        sddl="O:BAD:PAI(A;;FA;;;BA)(A;;FA;;;S-1-5-80-956008885-3418522649-1831038044-"
             "1853292631-2271478464)")
    add("null-dacl", "file", False, "null-dacl", sddl="O:BA")
    add("null-dacl-ancestor", "ancestor", False, "null-dacl", sddl="O:BA")
    add("empty-dacl", "file", True, None, sddl="O:BAD:P")
    add("callback-ace", "file", False, "ace-type",
        sddl='O:BAD:PAI(A;;FA;;;BA)(XA;;FR;;;BU;(WIN://SYSAPPID Contains "x"))')
    add("object-ace", "file", False, "ace-type",
        sddl="O:BAD:PAI(A;;FA;;;BA)(OA;;CC;bf967aba-0de6-11d0-a285-00aa003049e2;;BU)")
    add("object-ace-ancestor", "ancestor", False, "ace-type",
        sddl="O:BAD:PAI(A;;FA;;;BA)(OA;;CC;bf967aba-0de6-11d0-a285-00aa003049e2;;BU)")
    add("untrusted-owner", "file", False, "owner", sddl="O:BUD:PAI(A;;FA;;;BA)")
    add("user-owner", "file", False, "owner",
        sddl="O:S-1-5-21-1-2-3-1001D:PAI(A;;FA;;;BA)")
    add("system-owner", "file", True, None, sddl="O:SYD:PAI(A;;FA;;;BA)")
    add("no-owner", "file", False, "owner", sddl="D:PAI(A;;FA;;;BA)")
    add("unprotected-folder", "folder", False, "not-protected",
        sddl="O:BAD:AI(A;OICI;FA;;;BA)(A;OICI;0x1200a9;;;BU)")
    add("unprotected-file", "file", True, None,
        sddl="O:BAD:AI(A;;FA;;;BA)(A;;0x1200a9;;;BU)")
    add("reparse-file", "file", False, "reparse", sddl=FILE_SDDL, reparse=True)
    add("reparse-ancestor", "ancestor", False, "reparse", sddl=PROGRAM_DATA, reparse=True)
    add("program-data-ancestor", "ancestor", True, None, sddl=PROGRAM_DATA)
    add("ancestor-users-add-subdir", "ancestor", True, None,
        sddl="O:SYD:P(A;;FA;;;SY)(A;;0x1200a9;;;BU)(A;;0x4;;;BU)")
    add("ancestor-users-delete", "ancestor", False, "write-right",
        sddl="O:SYD:P(A;;FA;;;SY)(A;;SD;;;BU)")
    add("ancestor-users-delete-child", "ancestor", False, "write-right",
        sddl="O:SYD:P(A;;FA;;;SY)(A;;0x40;;;BU)")
    add("ancestor-users-write-dac", "ancestor", False, "write-right",
        sddl="O:SYD:P(A;;FA;;;SY)(A;;WD;;;BU)")
    add("ancestor-users-generic-all", "ancestor", False, "write-right",
        sddl="O:SYD:P(A;;FA;;;SY)(A;;GA;;;BU)")
    add("ancestor-untrusted-owner", "ancestor", False, "owner",
        sddl="O:BUD:P(A;;FA;;;SY)")
    add("owner-and-write", "file", False, "owner",
        sddl="O:BUD:PAI(A;;FA;;;BU)")

    good = sddl_to_bytes(FILE_SDDL)
    add("truncated", "file", False, "malformed", data=good[:30])
    add("too-short", "file", False, "malformed", data=good[:10])
    add("not-self-relative", "file", False, "malformed",
        data=patch(good, 2, "<H", struct.unpack_from("<H", good, 2)[0] & ~0x8000))
    add("bad-revision", "file", False, "malformed", data=patch(good, 0, "<B", 2))

    # Nested sizes: each structure must fit inside its container.
    first_ace = first_ace_offset(good)
    ace_size = struct.unpack_from("<H", good, first_ace + 2)[0]
    add("sid-past-ace-size", "file", False, "malformed",
        data=patch(good, first_ace + 2, "<H", ace_size - 4))
    acl_size = struct.unpack_from("<H", good, dacl_offset(good) + 2)[0]
    add("aces-past-acl-size", "file", False, "malformed",
        data=patch(good, dacl_offset(good) + 2, "<H", acl_size - 8))
    add("acl-size-past-buffer", "file", False, "malformed",
        data=patch(good, dacl_offset(good) + 2, "<H", len(good) + 64))
    add("ace-count-too-high", "file", False, "malformed",
        data=patch(good, dacl_offset(good) + 4, "<H", 50))
    sid_start = first_ace + 8
    # Zero sub-authorities is a valid SID structure (S-1-5), so the first entry
    # becomes "S-1-5 has full control": a write-right problem, not malformed.
    add("sid-zero-subauthorities", "file", False, "write-right",
        data=patch(good, sid_start + 1, "<B", 0))
    add("sid-sixteen-subauthorities", "file", False, "malformed",
        data=patch(good, sid_start + 1, "<B", 16))
    add("ace-size-below-header", "file", False, "malformed",
        data=patch(good, first_ace + 2, "<H", 2))
    add("owner-offset-past-buffer", "file", False, "malformed",
        data=patch(good, 4, "<I", len(good) + 4))

    out = HERE / "cases.json"
    # write_bytes keeps LF line endings and, unlike write_text(newline=...),
    # works on Python 3.9 (review finding CODE-002).
    out.write_bytes((json.dumps(cases, indent=1) + "\n").encode("utf-8"))
    print(f"wrote {len(cases)} cases to {out}")


if __name__ == "__main__":
    main()
